<script setup lang="ts">
import type { BackendRoomVariant } from '~~/shared/types/backend'
import { roomVariants } from '~/data/rooms'
import { formatMoney, rupiah } from '~/utils/money'

definePageMeta({ layout: 'staff' }); useSeoMeta({ title: 'Catalog management' })
const apiMode = computed(() => useRuntimeConfig().public.operationsMode === 'api')
const rooms = ref<BackendRoomVariant[]>([]); const selectedId = ref(''); const loading = ref(false); const error = ref(''); const notice = ref('')
const draft = reactive<BackendRoomVariant>({ id: '', code: '', name: '', family_name: '', bed_type: '', room_size_sqm: 0, max_capacity: 1, max_adults: 1, max_children: 0, description: '', base_price_minor: 0, amenities: [], photos: [] })
const { dirty, accept, restore } = useUnsavedChanges(() => draft)
const amenitiesText = computed({ get: () => draft.amenities.join('\n'), set: (value: string) => { draft.amenities = value.split('\n').map(item => item.trim()).filter(Boolean) } })
const reviewItems = computed(() => { const current = rooms.value.find(item => item.id === selectedId.value); return current ? [{ label: 'Nama', before: current.name, after: draft.name }, { label: 'Kapasitas', before: String(current.max_capacity), after: String(draft.max_capacity) }, { label: 'Harga dasar', before: formatMoney(rupiah(current.base_price_minor)), after: formatMoney(rupiah(draft.base_price_minor)) }, { label: 'Fasilitas', before: current.amenities.join(', '), after: draft.amenities.join(', ') }] : [] })
function mockRooms(): BackendRoomVariant[] { return roomVariants.map(room => ({ id: room.id, code: room.id, name: room.name, family_name: room.familyId, bed_type: room.bed, room_size_sqm: 0, max_capacity: room.capacity, max_adults: room.capacity, max_children: 0, description: 'Deskripsi sample mengikuti konten katalog booking.', base_price_minor: room.startingPrice?.amount || 0, amenities: [...room.features], photos: [{ url: '', alt: room.imageAlt }] })) }
function select(id: string, force = false) {
  if (dirty.value && !force && id !== selectedId.value && !window.confirm('Buang perubahan yang belum disimpan?')) return
  const room = rooms.value.find(item => item.id === id); if (!room) return
  selectedId.value = id; Object.assign(draft, structuredClone(toRaw(room))); accept(); notice.value = ''
}
async function load() {
  loading.value = true; error.value = ''
  try {
    rooms.value = apiMode.value ? (await $fetch<{ total: number, rooms: BackendRoomVariant[] }>('/api/bff/staff/catalog/rooms')).rooms : mockRooms()
    if (rooms.value.length) select(rooms.value[0]!.id, true)
  }
  catch (cause) { const value = cause as { statusMessage?: string, data?: { statusMessage?: string } }; error.value = value.data?.statusMessage || value.statusMessage || 'Katalog belum dapat dimuat.' }
  finally { loading.value = false }
}
function discard() { Object.assign(draft, restore()); notice.value = 'Perubahan yang belum disimpan dibuang.' }
function save() {
  if (apiMode.value) return
  const index = rooms.value.findIndex(item => item.id === selectedId.value); if (index >= 0) rooms.value[index] = structuredClone(toRaw(draft))
  accept(); notice.value = 'Perubahan katalog tersimpan pada simulasi browser ini. Quote live tidak berubah.'
}
onMounted(load)
onBeforeRouteLeave(() => !dirty.value || window.confirm('Tinggalkan editor dan buang perubahan yang belum disimpan?'))
</script>

<template><div class="container ops-page"><StaffPageHeader eyebrow="Catalog management" title="Katalog kamar" description="Kelola identitas varian, kapasitas, harga dasar, fasilitas, dan metadata foto dalam satu editor."><template #actions><StaffStatusBadge :label="apiMode ? 'Live read-only' : 'Sample editor'" :status="apiMode ? 'healthy' : 'neutral'" /></template></StaffPageHeader><UiInlineAlert v-if="notice" tone="info" live>{{ notice }}</UiInlineAlert><UiInlineAlert v-if="apiMode" tone="info">Katalog live dapat dibaca. Create, edit, dan delete tetap dikunci sampai permission mutation dan conflict policy diaktifkan.</UiInlineAlert><StaffDataState v-if="loading" loading loading-label="Memuat katalog…" /><StaffDataState v-else-if="error" :error="error" @retry="load" /><StaffDataState v-else-if="!rooms.length" empty empty-label="Belum ada varian kamar." /><div v-else class="ops-split"><section class="ops-grid catalog-list" aria-label="Daftar varian kamar"><article v-for="room in rooms" :key="room.id" class="ops-card" :class="{ 'ops-card--selected': selectedId === room.id }"><div class="ops-card__top"><div><p class="eyebrow">{{ room.code }} · {{ room.family_name }}</p><h3>{{ room.name }}</h3></div><StaffStatusBadge :label="`${room.max_capacity} tamu`" /></div><p>{{ room.bed_type }} · {{ room.room_size_sqm || '—' }} m²</p><strong>{{ formatMoney(rupiah(room.base_price_minor)) }}</strong><p class="muted">{{ room.amenities.join(' · ') || 'Belum ada fasilitas' }}</p><BrandButton @click="select(room.id)">{{ selectedId === room.id ? 'Sedang diedit' : 'Buka editor' }}</BrandButton></article></section><form class="panel stack catalog-editor" @submit.prevent="save"><div class="ops-card__top"><div><p class="eyebrow">{{ draft.code || 'Varian' }}</p><h2>Editor katalog</h2></div><StaffStatusBadge v-if="dirty" label="Belum disimpan" status="pending" /></div><div class="two-col"><div class="field"><label for="catalog-code">Kode</label><input id="catalog-code" v-model.trim="draft.code" required /></div><div class="field"><label for="catalog-name">Nama</label><input id="catalog-name" v-model.trim="draft.name" required /></div><div class="field"><label for="catalog-family">Family</label><input id="catalog-family" v-model.trim="draft.family_name" /></div><div class="field"><label for="catalog-bed">Tipe bed</label><input id="catalog-bed" v-model.trim="draft.bed_type" /></div><div class="field"><label for="catalog-size">Luas m²</label><input id="catalog-size" v-model.number="draft.room_size_sqm" type="number" min="0" /></div><div class="field"><label for="catalog-capacity">Kapasitas maksimum</label><input id="catalog-capacity" v-model.number="draft.max_capacity" type="number" min="1" required /></div><div class="field"><label for="catalog-adults">Maksimum dewasa</label><input id="catalog-adults" v-model.number="draft.max_adults" type="number" min="0" /></div><div class="field"><label for="catalog-children">Maksimum anak</label><input id="catalog-children" v-model.number="draft.max_children" type="number" min="0" /></div></div><div class="field"><label for="catalog-price">Harga dasar IDR</label><input id="catalog-price" v-model.number="draft.base_price_minor" type="number" min="1" step="1" required /><small>Harga ini menjadi sumber rate engine, bukan harga final untuk semua tanggal.</small></div><div class="field"><label for="catalog-description">Deskripsi</label><textarea id="catalog-description" v-model="draft.description" rows="5" /></div><div class="field"><label for="catalog-amenities">Fasilitas, satu per baris</label><textarea id="catalog-amenities" v-model="amenitiesText" rows="6" /></div><div class="field"><label>Metadata foto</label><div v-for="(photo, index) in draft.photos" :key="index" class="catalog-photo"><input v-model.trim="photo.url" :aria-label="`URL foto ${index + 1}`" placeholder="URL foto" /><input v-model.trim="photo.alt" :aria-label="`Teks alternatif foto ${index + 1}`" placeholder="Teks alternatif" /></div><small>Upload media belum tersedia; URL dan alt mengikuti kontrak katalog.</small></div><StaffChangeReview v-if="dirty" :items="reviewItems" /><div class="ops-actions"><BrandButton type="submit" dark :disabled="apiMode || !dirty">Simpan simulasi</BrandButton><BrandButton :disabled="!dirty" @click="discard">Buang perubahan</BrandButton></div></form></div></div></template>

<style scoped>.catalog-list { align-content: start; }.catalog-editor { position: sticky; top: 92px; max-height: calc(100vh - 120px); overflow-y: auto; }.catalog-photo { display: grid; gap: 8px; padding: 12px; border: 1px solid var(--line); border-radius: 14px; }@media (max-width: 719px) { .catalog-editor { position: static; max-height: none; } }</style>
